#include <bits/stdc++.h>
using namespace std;
const int MAXN = 10000010, INF = 0x3f3f3f3f;
int total_nodes, edges, c_value, d_value, k_value, total_cost = 0;
int start_node = 0, end_node, edge_count = 1, head[MAXN], to[MAXN], next_edge[MAXN], capacity[MAXN], weight[MAXN];
int distance[MAXN], flow_infinity[MAXN], predecessor_edge[MAXN]; bool in_queue[MAXN];

void add_edge(int x, int y, int cap, int w) {
	to[++edge_count] = y, next_edge[edge_count] = head[x], head[x] = edge_count, capacity[edge_count] = cap, weight[edge_count] = w;
	to[++edge_count] = x, next_edge[edge_count] = head[y], head[y] = edge_count, capacity[edge_count] = 0, weight[edge_count] = -w;
}
bool spfa() {
	memset(flow_infinity, 0, sizeof(flow_infinity));
	memset(distance, INF, sizeof(distance));
	memset(in_queue, 0, sizeof(in_queue));
	queue<int> q;
	q.push(start_node);
	flow_infinity[start_node] = INF;
	in_queue[start_node] = true;
	distance[start_node] = 0;
	while (!q.empty()) {
		int u = q.front(); q.pop(); in_queue[u] = false;
		for (int i = head[u]; i; i = next_edge[i]) {
			if (!capacity[i] || distance[to[i]] <= distance[u] + weight[i]) continue;
			distance[to[i]] = distance[u] + weight[i];
			flow_infinity[to[i]] = min(flow_infinity[u], capacity[i]);
			predecessor_edge[to[i]] = i;
			if (!in_queue[to[i]]) {
				in_queue[to[i]] = true;
				q.push(to[i]);
			}
		}
	}
	return distance[end_node] != INF;
}
void update_flow() {
	int tmp = end_node;
	while (tmp != start_node) {
		int i = predecessor_edge[tmp];
		capacity[i] -= flow_infinity[end_node];
		capacity[i ^ 1] += flow_infinity[end_node];
		tmp = to[i ^ 1];
	}
	total_cost += flow_infinity[end_node] * distance[end_node];
}
int main() {
	scanf("%d%d%d%d%d", &total_nodes, &edges, &k_value, &c_value, &d_value);
	end_node = (total_nodes + k_value - 1) * total_nodes + 1;
	for (int i = 1, x; i <= k_value; i++) {
		scanf("%d", &x);
		add_edge(start_node, x, 1, 0);
	}
	for (int i = 1, x, y; i <= edges; i++) {
		scanf("%d%d", &x, &y);
		for (int j = 1; j <= total_nodes + k_value; j++)
			for (int h = 1; h <= k_value; h++) {
				add_edge(x + (j - 1) * total_nodes, y + j * total_nodes, 1, d_value * h * 2 - d_value + c_value);
				add_edge(y + (j - 1) * total_nodes, x + j * total_nodes, 1, d_value * h * 2 - d_value + c_value);
			}
	}
	for (int i = 1; i < total_nodes + k_value; i++) {
		for (int j = 2; j <= total_nodes; j++)
			add_edge(j + (i - 1) * total_nodes, j + i * total_nodes, INF, c_value);
		add_edge(1 + (i - 1) * total_nodes, 1 + i * total_nodes, INF, 0);
	}
	while (spfa()) {
		update_flow();
	}
	printf("%d\n", total_cost);
	return 0;
}
